from lib import *
S = SS('g50')
steps = [
    step("实验环境:Docker Desktop 的 Linux 虚拟机有 10 个 CPU,cgroup 版本 2。我把同一份源码用 Go 1.27.1 交叉编译成 linux/arm64 静态程序,用 docker import 做成只含这一个文件的镜像,分别以 go.mod 写 go 1.27(g50:new)和 go 1.24(g50:old)各编一份。程序自己读 /sys/fs/cgroup/cpu.max、打印 NumCPU 与 GOMAXPROCS。", t=tl(S(1)), mark=lidx(S(1), '10 个 CPU', 'go 1.27'), kv=KV([['虚拟机', '10 个 CPU,cgroup v2,linux/aarch64'], ['g50:new', 'go.mod 写 go 1.27'], ['g50:old', 'go.mod 写 go 1.24,源码相同']], ['虚拟机'])),
    step("go 1.27 的程序,默认的 GOMAXPROCS 随容器的 CPU 限制变化(NumCPU 始终是 10):不限制 → 10;--cpus=4 → 4;--cpus=2 → 2;--cpus=2.5 → 3(向上取整);--cpus=1 → 2;--cpus=0.5 → 2;--cpuset-cpus=0-2 → 3(此时 NumCPU 本身就是 3,cpu.max 是 max)。限制为 1 或 0.5 个 CPU 时仍是 2。", t=tl(S(2)), done=lidx(S(2), '[--cpus=4]', '[--cpus=2]', '[--cpuset-cpus=0-2]'), mark=lidx(S(2), '[--cpus=2.5]', '[--cpus=1]', '[--cpus=0.5]'), b=bars([['不限制', 10, '10'], ['--cpus=4', 4, '4'], ['--cpus=2.5', 3, '3'], ['--cpus=2', 2, '2'], ['--cpus=1', 2, '2'], ['--cpus=0.5', 2, '2']], 10, done=[0, 1, 3], mark=[2, 4, 5]), kv=KV([['--cpus=2.5', 'GOMAXPROCS=3,向上取整'], ['--cpus=1 / 0.5', 'GOMAXPROCS=2,不会低于 2'], ['--cpuset-cpus=0-2', 'NumCPU=3,GOMAXPROCS=3']], ['--cpus=1 / 0.5'])),
    step("把同一份源码的 go.mod 改成 go 1.24,仍用 Go 1.27.1 编译:--cpus=2 时 GOMAXPROCS=10,--cpus=0.5 时也是 10,cpu.max 明明是 200000 100000 和 50000 100000——语言版本低时默认不看 cgroup。", t=tl(S(3)), done=lidx(S(3), '[--cpus=2]'), mark=lidx(S(3), '[--cpus=0.5]'), kv=KV([['go 1.24 + --cpus=2', 'GOMAXPROCS=10'], ['go 1.24 + --cpus=0.5', 'GOMAXPROCS=10'], ['原因', 'godebug 文档:containermaxprocs=0 是 go 1.24 及以下的默认']], ['原因'])),
    step("手动覆盖(go 1.27 的程序,都在 --cpus=2 下):环境变量 GOMAXPROCS=8 → 8;GODEBUG=containermaxprocs=0 → 10(回到 NumCPU)。", t=tl(S(4)), done=lidx(S(4), 'GOMAXPROCS=8'), mark=lidx(S(4), 'containermaxprocs=0'), kv=KV([['GOMAXPROCS=8', '8,无视 cgroup'], ['containermaxprocs=0', '10,等于 NumCPU']], ['GOMAXPROCS=8'])),
    step("运行中改限制:容器以 --cpus=2 启动,约 2.2 秒后 docker update --cpus=4,再约 2 秒后改成 1。程序每 0.5 秒打印一次:cpu.max 在 t=2.5 s 已是 400000;GOMAXPROCS 到 t=3.5 s 才变成 4;cpu.max 在 t=4.5 s 变成 100000;GOMAXPROCS 到 t=5.5 s 变成 2。每次的滞后约 1 秒。", t=tl(S(5)), done=lidx(S(5), 't= 2.5s', 't= 4.5s'), mark=lidx(S(5), 't= 3.5s', 't= 5.5s'), kv=KV([['cpu.max 变化', 't=2.5 s 和 t=4.5 s 可见'], ['GOMAXPROCS 变化', 't=3.5 s 和 t=5.5 s 才变'], ['滞后', '约 1 秒']], ['滞后'])),
    step("很并行的程序(10 个空转 goroutine 加 1 ms 睡眠计时,跑 3 秒)在 --cpus=1 下,重复 3 次:默认 GOMAXPROCS=2:cgroup 记录的 throttled_usec 为 3.0 / 2.97 / 3.01 秒,最坏的 1 ms 睡眠超时 86.3 / 104.8 / 95.4 ms;强制 GOMAXPROCS=10:throttled_usec 为 27.2 / 28.2 / 27.3 秒,最坏超时 214.5 / 207.7 / 206.3 ms,3 秒内只完成 21 / 22 / 20 次睡眠(默认为 77 / 69 / 74 次)。", t=tl(S(6)), done=lidx(S(6), '[默认]'), mark=lidx(S(6), '[GOMAXPROCS=10]'), b=bars([['默认 GOMAXPROCS=2:throttled(秒)', 3.0, '3.0'], ['GOMAXPROCS=10:throttled(秒)', 27.2, '27.2'], ['默认:最坏睡眠超时(ms÷10)', 8.6, '86 ms'], ['GOMAXPROCS=10:最坏超时(ms÷10)', 21.5, '215 ms']], 27.2, done=[0, 2], mark=[1, 3]), kv=KV([['默认(2)', 'throttled 约 3 秒,最坏超时 86–105 ms'], ['强制 10', 'throttled 约 27–28 秒,最坏超时 206–215 ms'], ['注意', '默认值 2 仍高于 1 个 CPU 的限制,依然被限流']], ['注意'])),
    step("文档怎么说(go doc runtime.GOMAXPROCS 与 godebug 文档原文):默认值取逻辑 CPU 数、亲和性掩码数、cgroup CPU 吞吐限制三者的最小值,但 never set GOMAXPROCS less than 2 unless 逻辑 CPU 数或亲和性掩码数低于 2;限制不是整数时 rounds up to the next whole number;更新 up to once per second。godebug 文档:Go 1.25 新增 containermaxprocs 与 updatemaxprocs 两个设置,默认值都是 1。", t=tl(S(7)), done=lidx(S(7), 'less than 2', 'rounds up', 'once per second'), mark=lidx(S(7), 'containermaxprocs=0 is default', 'updatemaxprocs'), kv=KV([['取值', '三者最小,不低于 2'], ['非整数', '向上取整'], ['更新', '最多每秒一次'], ['开关', 'containermaxprocs / updatemaxprocs,Go 1.25 新增']], ['取值'])),
]
A = mkartg('g50', 50, 'Go,GOMAXPROCS,容器,cgroup,CPU限流,真实验证,动画演示',
    '在 Docker(Linux 虚拟机、cgroup v2)里验证 Go 1.27.1 的默认 GOMAXPROCS:按 --cpus 取值(2.5 → 3,1 或 0.5 → 2),go.mod 写 go 1.24 时仍是 10,运行中改限制约 1 秒后跟随,并在 --cpus=1 下对比默认值 2 与强制 10 的 CPU 限流时间(约 3 秒 vs 约 27 秒)。',
    '容器里限制了 CPU,Go 程序默认起多少个 P?Go 1.25 之前它看不见 cgroup 限制,容易被限流拖慢。这篇用不同的 --cpus 设置、不同的 go.mod 语言版本和运行中修改限制,实测默认值怎么变,以及选错的代价。',
    [('2.5 → 3', '--cpus=2.5 时的默认 GOMAXPROCS,向上取整'), ('不低于 2', '--cpus=1 与 --cpus=0.5 时默认值都是 2'), ('3 s vs 27 s', '--cpus=1 下默认值与强制 GOMAXPROCS=10 的 cgroup 限流时间(3 秒的空转)')],
    [('实验环境', '<p>宿主是 Docker Desktop 的 Linux 虚拟机(10 个 CPU,cgroup 版本 2),所以读到的 <code>cpu.max</code> 是 cgroup v2 的文件。程序是同一份源码交叉编译的静态二进制,没有其它依赖;cgroup v1 的情形我没有测。</p>'),
     ('默认值跟着 cgroup 走', '<p>go.mod 写 go 1.27 的程序,GOMAXPROCS 默认取 NumCPU 与 cgroup 限制中小的那个,非整数向上取整(2.5 → 3)。限制低于 2 个 CPU 时也是 2,文档写明“除非逻辑 CPU 数低于 2,否则不会低于 2”。</p>'),
     ('语言版本决定默认行为', '<p>同一份源码、同一个编译器,仅 go.mod 的 <code>go</code> 行从 1.27 改成 1.24,容器限制 2 个 CPU 时 GOMAXPROCS 就从 2 变成 10。godebug 文档说明 <code>containermaxprocs=0</code> 是 go 1.24 及以下的默认。所以老项目升级编译器但没改 go.mod,不会自动获得这个行为。</p>'),
     ('手动设置优先', '<p>环境变量 <code>GOMAXPROCS=8</code> 无视 cgroup 直接取 8;<code>GODEBUG=containermaxprocs=0</code> 则回到 NumCPU。</p>'),
     ('运行中会更新', '<p><code>docker update --cpus</code> 改了限制后,cpu.max 立刻变化,GOMAXPROCS 在大约 1 秒后跟上,与文档里“最多每秒更新一次”一致。</p>'),
     ('选错的代价', '<p>在 <code>--cpus=1</code> 下让 10 个线程并行空转,cgroup 记录的限流时间是默认值(2)的约 9 倍,1 ms 睡眠最坏被拖到约 210 ms(默认约 90 ms)。注意默认值 2 仍高于 1 个 CPU 的限制,所以仍被限流,只是轻得多。throttled_usec 是累计量,为什么恰好是 3 秒和 27 秒左右,我没有推导,只报告观察到的数。</p>'),
     ('文档里的规则', '<p>规则都来自 <code>go doc runtime.GOMAXPROCS</code> 与 godebug 文档:三者取最小、不低于 2、向上取整、每秒最多更新一次。实验的每一项都与这几条吻合。</p>')],
    steps,
    [ENV_G + '。容器环境:Docker 29.8.2(Docker Desktop,Linux 虚拟机 10 个 CPU,cgroup v2,linux/aarch64);程序为 CGO_ENABLED=0 交叉编译的静态二进制,用 docker import 做成单文件镜像,实验后已删除;cpu.max 与 cpu.stat 是程序在容器内读的;“burn”实验每组重复 3 次;读过的文档:go doc runtime.GOMAXPROCS、$GOROOT/doc/godebug.md 中 containermaxprocs 与 updatemaxprocs 的段落',
     '没有验证:cgroup v1、Kubernetes 的 requests/limits 与 GOMAXPROCS 的关系、cpu.max 为非整数且小于 1 时之外的更多取值、throttled_usec 的具体换算、Linux 物理机(而非 Docker Desktop 虚拟机)上的表现、其它 GOMAXPROCS 值(如 4、6)下的限流曲线、真实业务负载下 GOMAXPROCS 对延迟的影响'],
    'GOMAXPROCS 与容器')
